// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract CallProxy {
    C public target;
    constructor(C _target) {
        target = _target;
    }
    function proxiedOwner() external view returns (address) {
        return target.owner();
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed param is an arbitrary caller address used to deploy and call through a contract
    function testFuzz_property(address caller) public {
        // avoid zero address proxy deployer to keep domain wide but sensible
        vm.assume(caller != address(0));

        // Deploy a proxy contract from 'caller' so msg.sender inside C will be the proxy, while tx.origin is 'caller'
        vm.prank(caller);
        CallProxy proxy = new CallProxy(c);

        // Call owner() directly (as an EOA) to observe stored owner (should be address(this) from setUp)
        address owner_direct = c.owner();

        // Call owner() via proxy contract so msg.sender inside C == address(proxy) and tx.origin == caller
        address owner_via_proxy = proxy.proxiedOwner();

        // General property: owner returned directly and owner returned when called via an intermediate contract should be equal
        // In correct contract both return the stored owner (set in constructor). The mutant returning tx.origin will make these differ for some caller (fuzzer can find one).
        assertTrue(owner_direct == owner_via_proxy);
    }
}

