pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract CallerHelper {
    function getOwner(address c) external view returns (address) {
        return C(c).owner();
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz a random externally owned address to act as tx.origin when calling through a contract
    function testFuzz_property(address originEOA) public {
        // Keep admissible domain wide but non-zero address
        // allow zero too, since owner at construction is address(this) (the test contract)
        // Deploy a helper contract that will call c.owner() from a contract context
        CallerHelper helper = new CallerHelper();

        // We want to simulate a call where tx.origin == originEOA. To do that, we use vm.prank
        // to set msg.sender for the external call that invokes helper; vm.prank sets both tx.origin and msg.sender
        // in Foundry single-call pranks, tx.origin becomes the prank address for the top-level call.
        // Ensure originEOA is not the test contract itself to create a difference scenario; but keep wide domain.

        // If originEOA equals address(this) then both reference and mutant return same value (no distinction).
        // We don't restrict it out; the fuzzer will find a differing origin.

        // Call helper.getOwner with tx.origin set to originEOA so that inside helper: msg.sender=helper, tx.origin=originEOA
        vm.prank(originEOA);
        address ownerReturnedFromHelper = helper.getOwner(address(c));

        // The reference implementation always returns the stored owner (set at construction to address(this)).
        address storedOwner = c.owner();

        // General rule: calling owner() through another contract must return the same stored owner as calling owner() directly.
        // In the correct contract, both are equal for all inputs. The mutant returning tx.origin will make them differ when tx.origin != storedOwner.
        assertTrue(ownerReturnedFromHelper == storedOwner);
    }
}

