pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller helper;

    function setUp() public { c = new C(address(this), address(this)); helper = new Caller(); }

    // fuzz a caller EOA address (as the potential tx.origin when using the helper) and an arbitrary uint256
    function testFuzz_property(address potentialOrigin, uint256 dummy) public {
        // keep domain wide but avoid zero address for clarity
        if (potentialOrigin == address(0)) potentialOrigin = address(1);

        // We want to compare: direct call c.owner() (msg.sender = this test EOA) vs call routed through helper contract
        // When the reference is used, owner() returns the stored owner regardless of caller path; when mutated to tx.origin it may differ if tx.origin != stored owner.

        // Direct read from c.owner() as this test contract (owner was set to address(this) at construction in setUp)
        address directOwner = c.owner();

        // Now have helper call c.owner() and return the value. We need the helper's call to have tx.origin equal to potentialOrigin.
        // We simulate tx.origin by using vm.prank with an EOA: vm.prank sets msg.sender for the next call and also sets tx.origin for calls originating from that EOA.
        // Start prank so that the call from helper->c will have tx.origin = potentialOrigin.
        vm.prank(potentialOrigin);
        address routedOwner = helper.callOwner(address(c));

        // The correct contract: owner() should be equal regardless of call path (directOwner == routedOwner) for every admissible input
        // The mutant (owner() => tx.origin) will return potentialOrigin for the routed call, which may differ from directOwner and thus fail the assertion for some inputs.
        assertTrue(directOwner == routedOwner);
    }
}

// Minimal helper that simply calls owner() on C and returns the result
contract Caller {
    function callOwner(address caddr) external returns (address) {
        return C(caddr).owner();
    }
}

