pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract CallerHelper {
    function callOwner(address c) external returns (address) {
        // call owner() on C and return the reported address
        (bool ok, bytes memory ret) = c.call(abi.encodeWithSignature("owner()"));
        require(ok, "call failed");
        return abi.decode(ret, (address));
    }
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed parameter is the caller EOA (as address). The property: for any caller EOA,
    // the result of calling owner() directly from that EOA equals the result when that EOA
    // deploys a contract and that contract calls owner() (intermediate call). The buggy
    // mutant returning tx.origin will break this for some callers.
    function testFuzz_property(address caller) public {
        // avoid zero address as a caller (admissible domain wide but zero-address pranks are not meaningful)
        vm.assume(caller != address(0));

        // Ensure caller has some ETH to deploy helper
        vm.deal(caller, 1 ether);

        // Direct call: have the EOA caller call c.owner()
        address directOwner;
        vm.prank(caller);
        directOwner = c.owner();

        // Indirect call: the EOA deploys a helper contract which in turn calls c.owner()
        vm.startPrank(caller);
        CallerHelper helper = new CallerHelper();
        address indirectOwner = helper.callOwner(address(c));
        vm.stopPrank();

        // The correct contract always returns the stored owner irrespective of call stack;
        // therefore directOwner == indirectOwner for all callers. The mutant returning tx.origin
        // will make these differ for some caller (the fuzzer will find such a caller).
        assertTrue(directOwner == indirectOwner);
    }
}

