pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz parameter is an address 'caller' (the EOA that will either call directly or deploy a helper)
    function testFuzz_property(address caller) public {
        // keep caller in wide admissible domain but not zero address (zero can be weird for prank)
        if (caller == address(0)) caller = address(1);

        // Direct call: have caller call c.owner() and capture returned address
        address directOwner;
        vm.prank(caller);
        try c.owner() returns (address o) {
            directOwner = o;
        } catch {
            // owner() is a view and should not revert; if it reverts, set to zero
            directOwner = address(0);
        }

        // Indirect call: caller deploys a minimal caller contract which calls c.owner() and returns it
        vm.prank(caller);
        IndirectCaller helper = new IndirectCaller();

        address viaOwner;
        // Have the helper contract call c.owner() (msg.sender inside c will be helper, tx.origin will be caller)
        try helper.callOwner(address(c)) returns (address o) {
            viaOwner = o;
        } catch {
            viaOwner = address(0);
        }

        // General rule: both results must be equal for the correct contract for ALL callers
        // The mutant returning tx.origin will make them differ for some caller (fuzzer should find one)
        assertTrue(directOwner == viaOwner);
    }
}

// helper that simply invokes owner() on target and returns the result
contract IndirectCaller {
    function callOwner(address target) external returns (address) {
        return C(target).owner();
    }
}

