pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzzed parameter is the address to transfer ownership to.
    // We deploy an actor contract that overrides _msgSender() to return a different address.
    function testFuzz_property(address newOwner) public {
        // keep newOwner wide but avoid zero so transferOwnership requirement in reference is still exercised
        vm.assume(newOwner != address(0));

        // Deploy a forwarder that will call transferOwnership on behalf of its overridden _msgSender
        CallerOverridingMsgSender caller = new CallerOverridingMsgSender(address(c), newOwner);

        // The CallerOverridingMsgSender will call c.transferOwnership(newOwner) from its own address.
        // In the reference contract, Ownable.onlyOwner uses _msgSender(), which for c (not overridden) equals msg.sender,
        // but the difference we want to detect is when the calling contract *overrides* _msgSender in its own context and
        // then calls c.transferOwnership; the mutant that tightens onlyOwner to compare owner() == msg.sender
        // (instead of _msgSender()) can behave differently when callers rely on an override. To produce that scenario,
        // we make the caller call c.transferOwnership while having a different reported sender inside the caller.

        // Make caller execute the transferOwnership call
        caller.callTransferOwnership();

        // Single assertion: after the call, the owner() of c must equal newOwner in the correct contract.
        // The mutant may prevent this when it compares to msg.sender directly and the caller relied on overriding _msgSender().
        assertTrue(c.owner() == newOwner);
    }
}

// Helper contract that simulates a caller which overrides _msgSender() behavior in its own context.
contract CallerOverridingMsgSender {
    address public target;
    address public newOwner;
    constructor(address _target, address _newOwner) {
        target = _target;
        newOwner = _newOwner;
    }

    // This contract intentionally defines _msgSender() differently (not used by c),
    // to model a caller that might rely on such an override in more complex setups.
    function _msgSender() internal view returns (address) {
        // return an address different from this contract to simulate an override
        return address(0xABCD);
    }

    function callTransferOwnership() public {
        // call into c.transferOwnership as this contract
        C(target).transferOwnership(newOwner);
    }
}

